  var root = document.querySelector('#app') || document.body.firstElementChild;
  var vm = root && root.__vue__;
  if(!vm) return {error:'no vue root', rootTag: root && root.tagName};
  var found=[];
  function walk(c){
    if(!c) return;
    try{
      if(c.extraPerms && c.businessName==='pubRevenueContract'){
        found.push({
          extraPerms: JSON.parse(JSON.stringify(c.extraPerms)),
          perms: JSON.parse(JSON.stringify(c.perms)),
          permsPrefix: c.permsPrefix,
          businessName: c.businessName,
          moduleName: c.moduleName,
          opButtons: (c.operationButtons||[]).map(function(b){return {label:b.label, permission:(b.attrs&&b.attrs.permission)||null};})
        });
      }
    }catch(e){}
    (c.$children||[]).forEach(walk);
  }
  walk(vm);
  return {count:found.length, data:found};
})()
